{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "The closest retrieved structure is furosemide acyl glucuronide, but its measured F of 0.15 is for the glucuronide metabolite, not the parent furosemide; this highly polar conjugate is not affirmative evidence for low parent oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Azosemide, a close furosemide analogue, had only about 10% oral bioavailability in patients, providing some contradictory evidence that certain analogues in this class can be low; however, its tetrazole/thiophene substitution and patient population limit direct transfer to furosemide.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C43"],
      "claim": "Bumetanide, a structurally related sulfamoylbenzoic acid loop diuretic, had absolute oral bioavailability of 0.588 ± 0.096 in healthy subjects, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In patients with alcoholic cirrhosis, tolfenamic acid showed about 100% oral bioavailability, demonstrating that high oral bioavailability is achievable under the query condition for a lipophilic carboxylic acid drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Hydrochlorothiazide, another sulfonamide diuretic, has absolute oral bioavailability of approximately 60–70%, supporting high F for the sulfonamide diuretic class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is furosemide. Although the closest parent analogue azosemide shows low/borderline bioavailability, the weight of direct class evidence from bumetanide, tolfenamic acid in cirrhosis, and hydrochlorothiazide supports F ≥ 20%. The low value for furosemide acyl glucuronide is a metabolite measurement and does not directly reflect parent furosemide bioavailability.",
  "evidence_gaps": [
    "No direct furosemide oral bioavailability record under cirrhosis is present in the supplied evidence.",
    "The closest analogue azosemide has structural differences (tetrazole/thiophene vs carboxylate/furan) that limit quantitative transfer.",
    "The highest-similarity record measures a metabolite, not the parent drug."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

